const collections=[
 {id:'velvet',title:'The Velvet Edit',type:'film',label:'SIGNATURE FILM',detail:'Sample film · 08:30',price:18,art:1,symbol:'✧',description:'A cinematic collection inspired by plum velvet, soft light, and an evening away from the ordinary.'},
 {id:'silver',title:'Silver Hour',type:'photos',label:'PHOTO COLLECTION',detail:'Sample collection · 24 photographs',price:12,art:2,symbol:'◇',description:'An editorial photo collection with platinum highlights and a quietly luxurious atmosphere.'},
 {id:'midnight',title:'Midnight Notes',type:'member',label:'MEMBER COLLECTION',detail:'Sample film · 06:15',price:null,art:3,symbol:'✦',description:'A more personal chapter in the member collection. This is illustrative content for the website preview.'}
];
const saved=new Set();
try{const ids=JSON.parse(localStorage.getItem('pad-saved')||'[]');if(Array.isArray(ids))ids.filter(id=>collections.some(c=>c.id===id)).forEach(id=>saved.add(id));}catch{}
const modal=document.querySelector('#modal'),body=document.querySelector('#modal-body');
function open(html){body.innerHTML=html;if(!modal.open)modal.showModal();}
function art(c){return `<div class="art art-${c.art}"><span class="art-symbol" aria-hidden="true">${c.symbol}</span><span class="tag">${c.label}</span><div class="art-bottom"><span>PLATINUM AFTER DARK</span><span>PREVIEW</span></div></div>`;}
function render(filter='all'){document.querySelector('#cards').innerHTML=collections.filter(c=>filter==='all'||c.type===filter).map(c=>`<article>${art(c)}<h3 class="collection-title">${c.title}</h3><div class="card-meta">${c.detail}</div><div class="card-bottom"><strong>${c.price===null?'Included with membership':`$${c.price} · Sample price`}</strong><button data-preview="${c.id}">View collection ↗</button></div></article>`).join('');}
function preview(id){const c=collections.find(c=>c.id===id);if(!c)return;open(`${art(c)}<h2>${c.title}</h2><p>${c.description}</p><p>${c.detail}. No media is uploaded in this prototype.</p><button class="button platinum" data-save="${c.id}">${saved.has(c.id)?'Remove from saved':'Save to preview library'} <span>◇</span></button><p>Saving is a browser-local demonstration. It does not purchase or unlock content.</p>`);}
function updateCount(){document.querySelector('#saved-count').textContent=saved.size;}
function library(){open(`<p class="eyebrow">YOUR PERSONAL SPACE</p><h2>My preview library</h2><p>Saved collections on this browser. Purchases and member access will appear here once the platform is connected.</p>${saved.size?[...saved].map(id=>{const c=collections.find(c=>c.id===id);return `<div class="library-row"><div>${c.title}<br><small>Saved preview · Not a purchase</small></div><button data-preview="${id}">View ↗</button></div>`;}).join(''):'<p>No saved collections yet. Explore the collection and save something you like.</p><button class="button platinum" data-browse>Explore collections ↗</button>'}`);}
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});render(button.dataset.filter);}));
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.preview)preview(b.dataset.preview);if(b.dataset.save){const id=b.dataset.save;if(saved.has(id))saved.delete(id);else saved.add(id);try{localStorage.setItem('pad-saved',JSON.stringify([...saved]));}catch{}updateCount();preview(id);}if(b.hasAttribute('data-library'))library();if(b.hasAttribute('data-browse')){modal.close();document.querySelector('#collection').scrollIntoView({behavior:'smooth'});}if(b.dataset.info){const text={privacy:['Privacy','This prototype stores only saved collection IDs in this browser. It does not collect payments or create customer accounts. A full privacy policy will be prepared for the selected platform before launch.'],terms:['Terms','This is a design demonstration for adults 18+. All collections, prices, and benefits are illustrative. No purchases, subscriptions, or live access are offered here. Final purchase and access terms will be provided before launch.'],support:['Support','Customer support details will be published before launch. For now, share design feedback through the project conversation.']}[b.dataset.info];open(`<h2>${text[0]}</h2><p>${text[1]}</p>`);}});
document.querySelector('.close').addEventListener('click',()=>modal.close());modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
document.querySelector('#join').addEventListener('click',()=>open('<p class="eyebrow">THE PLATINUM MEMBERSHIP</p><h2>Your invitation awaits.</h2><p>The membership experience is being designed. The displayed $24 monthly price is illustrative and billing is not connected.</p><p>Before launch, this step will lead to secure checkout through the approved payment provider. No payment details are collected in this preview.</p>'));
document.querySelector('#show-live').addEventListener('click',()=>open('<p class="eyebrow">THE LIVE LOUNGE</p><h2>A front-row evening.</h2><p>This space will show broadcast availability, the next scheduled appearance, and whether access is included with membership or requires a separate ticket.</p><p>No broadcast is scheduled or connected yet. Streaming integration and final access options are pending provider selection.</p>'));
document.querySelector('#year').textContent=new Date().getFullYear();render();updateCount();

// Keep selected navigation consistent with the section currently being viewed.
const navigation=document.querySelector('nav');
const homeLink=document.createElement('a');homeLink.href='#home';homeLink.textContent='Home';navigation.prepend(homeLink);
const sectionLinks=[...navigation.querySelectorAll('a[href^="#"]')];
const navigationSections=sectionLinks.map(link=>({link,section:document.querySelector(link.getAttribute('href'))})).filter(item=>item.section);
function syncNavigation(){const readingLine=window.scrollY+window.innerHeight*.3;let selected=navigationSections[0];for(const item of navigationSections){if(item.section.getBoundingClientRect().top+window.scrollY<=readingLine)selected=item;}for(const item of navigationSections){const active=item===selected;item.link.classList.toggle('is-active',active);if(active)item.link.setAttribute('aria-current','location');else item.link.removeAttribute('aria-current');}}
let navigationFrame=0;function queueNavigation(){if(navigationFrame)return;navigationFrame=requestAnimationFrame(()=>{navigationFrame=0;syncNavigation();});}
window.addEventListener('scroll',queueNavigation,{passive:true});window.addEventListener('resize',queueNavigation);window.addEventListener('hashchange',queueNavigation);syncNavigation();
